package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import io.tenvyr.control.authority.*;
import java.time.Instant;
import java.util.*;

/** Bounded views of durable facts. Neither reading nor polling mutates authority. */
public final class WorkbenchProjectionService {
    public static final ObjectNode BOUNDS=Json.object("maxExecutionsPerPage",50,"maxGoalChars",4096,"maxIterations",100,"maxWorkersPerIteration",64,"maxAttemptsPerExecution",200,"maxArtifactRefs",64,"maxReasonChars",512,"maxNameChars",255);
    private final Db db;private final RuntimeConnectionService connections;private final ExecutionCapsuleService capsules;private final DelegationService delegation;
    public WorkbenchProjectionService(Db db,RuntimeConnectionService connections,ExecutionCapsuleService capsules){this(db,connections,capsules,new DelegationService(db,new PolicyService(db)));}
    public WorkbenchProjectionService(Db db,RuntimeConnectionService connections,ExecutionCapsuleService capsules,DelegationService delegation){this.db=db;this.connections=connections;this.capsules=capsules;this.delegation=delegation;}
    public ObjectNode capsuleFor(String id){ObjectNode capsule=capsules.build(id),header=Json.object();for(String key:List.of("stepCount","revisionCount","attemptCount","budget","policy","approvals","delegation","artifacts"))header.set(key,Json.get(capsule.path("header"),key));return Json.object("schemaVersion",capsule.get("schemaVersion"),"pointInTime",capsule.get("pointInTime"),"sourceStatus",capsule.get("sourceStatus"),"contentHash",capsule.get("contentHash"),"header",header,"coordination",Json.get(capsule,"coordination"),"evidenceCompleteness",capsule.get("evidenceCompleteness"));}
    public ObjectNode connectionCards(){ArrayNode cards=Json.array();for(ObjectNode row:db.query("SELECT * FROM runtime_connections ORDER BY \"createdAt\" ASC")){ObjectNode revision=db.one("SELECT profile FROM connection_revisions WHERE \"connectionId\"=? ORDER BY \"revisionNumber\" DESC LIMIT 1",row.get("connectionId"));ArrayNode capabilities=Json.array();if(revision!=null)revision.path("profile").path("declaredCapabilities").fields().forEachRemaining(e->{if(capabilities.size()<64)capabilities.add(Json.object("key",e.getKey(),"supported",e.getValue().isBoolean()?e.getValue().asBoolean():Json.bool(e.getValue(),"supported",false),"source","declared"));});cards.add(Json.object("connectionId",row.get("connectionId"),"name",HandoffService.truncate(Json.text(row,"name",""),255),"runtimeKind",row.get("runtimeKind"),"executorId",row.get("executorId"),"testedVersion",row.hasNonNull("statusTestedVersion")?row.get("statusTestedVersion"):Json.get(row,"version"),"status",Json.text(row,"statusState","UNKNOWN"),"reasonCode",Json.get(row,"statusReasonCode"),"testedAt",Json.get(row,"statusTestedAt"),"capabilities",capabilities,"revoked",Json.text(row,"statusState","").equals("REVOKED")));}return Json.object("cards",cards,"serverTime",Instant.now().toString());}
    public ObjectNode executionSummaries(int page){page=Math.max(1,page);List<ObjectNode> rows=db.query("SELECT e.id,e.status,e.\"createdAt\",e.\"updatedAt\",e.\"terminationReason\",r.phase AS \"coordinationPhase\",r.\"currentIterationNumber\" AS \"iterationNumber\",(SELECT count(*)::int FROM step_executions s WHERE s.\"executionId\"=e.id) AS \"stepCount\" FROM executions e LEFT JOIN coordination_runs r ON r.\"executionId\"=e.id ORDER BY e.\"createdAt\" DESC LIMIT 50 OFFSET ?",(long)(page-1)*50);return Json.object("items",rows,"serverTime",Instant.now().toString(),"page",page,"truncated",rows.size()==50);}
    public ObjectNode executionProjection(String id){return db.transaction(tx->{tx.connection().setTransactionIsolation(java.sql.Connection.TRANSACTION_REPEATABLE_READ);return projection(tx,id);});}
    private ObjectNode projection(Db tx,String id){ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=?",id);if(execution==null)throw new RuntimeFailure("EXECUTION_NOT_FOUND","Execution does not exist");String goal=Json.stringify(Json.get(execution,"input"));ObjectNode executionView=Json.object("id",execution.get("id"),"status",execution.get("status"),"createdAt",execution.get("createdAt"),"updatedAt",execution.get("updatedAt"),"terminationReason",HandoffService.truncate(Json.text(execution,"terminationReason",null),512),"goal",Json.object("preview",HandoffService.truncate(goal,4096),"truncated",goal.length()>4096),"planRevisionCount",count(tx,"SELECT count(*) n FROM execution_plan_revisions WHERE \"executionId\"=?",id),"activePlanRevisionId",Json.get(execution,"activePlanRevisionId"));Map<String,ObjectNode> steps=new HashMap<>();for(ObjectNode step:tx.query("SELECT id,\"stepId\",status FROM step_executions WHERE \"executionId\"=?",id))steps.put(Json.text(step,"id"),step);ObjectNode run=tx.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?",id),coordination=null;if(run!=null){List<ObjectNode> iterations=tx.query("SELECT * FROM coordination_iterations WHERE \"coordinationRunId\"=? ORDER BY \"iterationNumber\" ASC LIMIT 101",run.get("id"));ArrayNode views=Json.array();for(ObjectNode iteration:iterations.subList(0,Math.min(100,iterations.size()))){ArrayNode manifest=Json.array();for(JsonNode item:iteration.path("workerManifest")){if(manifest.size()>=64)break;ObjectNode step=steps.get(Json.text(item,"logicalStepId"));manifest.add(Json.object("taskId",item.get("taskId"),"logicalStepId",item.get("logicalStepId"),"required",item.get("required"),"status",step==null?"UNKNOWN":Json.text(step,"status")));}JsonNode proposal=iteration.get("plannerProposal"),decision=iteration.path("decision");ObjectNode proposalView=null,recommendation=null;if(proposal!=null&&!proposal.isNull()){ArrayNode tasks=Json.array();for(JsonNode task:proposal.path("tasks")){if(tasks.size()>=64)break;ObjectNode taskView=Json.object("taskId",task.get("taskId"),"agent",task.get("agent"),"required",Json.bool(task,"required",false),"dependsOn",boundedList(task.path("dependsOn"),16),"reason",HandoffService.truncate(Json.text(task,"reason",""),512));if(task.hasNonNull("connectionId"))taskView.set("connectionId",task.get("connectionId"));tasks.add(taskView);}proposalView=Json.object("reason",HandoffService.truncate(Json.text(proposal,"reason",""),512),"tasks",tasks);}if(decision.hasNonNull("recommendation"))recommendation=Json.object("reason",HandoffService.truncate(Json.text(decision.path("recommendation"),"reason",""),512),"focus",boundedList(decision.path("recommendation").path("focus"),16));views.add(Json.object("iterationNumber",iteration.get("iterationNumber"),"plannerStepId",Json.get(iteration,"plannerStepId"),"plannerProposal",proposalView,"workerManifest",manifest,"verifierStepId",Json.get(iteration,"verifierStepId"),"decisionAction",Json.get(decision,"action"),"decisionReason",HandoffService.truncate(Json.text(decision,"reason",null),512),"decisionRecommendation",recommendation,"decisionHash",Json.get(iteration,"decisionHash"),"outcome",Json.get(iteration,"outcome")));}JsonNode config=run.path("config");ObjectNode lease=tx.one("SELECT * FROM workspace_executions WHERE \"ownerRunId\"=?",run.get("id"));JsonNode leaseView=lease==null||!lease.hasNonNull("executionPath")?null:Json.object("workspaceExecutionId",lease.get("id"),"mode",lease.get("mode"),"path",lease.get("executionPath"),"baseBranch",Json.get(lease,"baseBranch"),"baseHeadSha",Json.get(lease,"baseHeadSha"),"state",lease.get("state"),"hasUncommittedWork",Json.get(lease,"hasUncommittedWork"));coordination=Json.object("run",Json.object("runId",run.get("id"),"phase",run.get("phase"),"currentIterationNumber",run.get("currentIterationNumber"),"cumulativeWorkers",run.get("cumulativeWorkers"),"maxIterations",config.get("maxIterations"),"maxWorkersPerIteration",config.get("maxWorkersPerIteration"),"maxTotalWorkers",config.get("maxTotalWorkers"),"remainingDeadlineMs",Math.max(0,Instant.parse(Json.text(run,"loopDeadlineAt")).toEpochMilli()-System.currentTimeMillis()),"budgetAccountId",Json.get(config,"budgetAccountId"),"waitReason",Json.get(run,"waitReason"),"workspace",Json.get(run,"workspace"),"acceptanceEvidence",Json.get(run,"acceptanceEvidence"),"executionWorkspace",leaseView),"iterations",views,"truncated",iterations.size()>100);}
        List<ObjectNode> attempts=tx.query("SELECT * FROM step_attempts WHERE \"executionId\"=? ORDER BY \"createdAt\" DESC LIMIT 200",id);ArrayNode attemptViews=Json.array();for(ObjectNode attempt:attempts){ObjectNode step=steps.get(Json.text(attempt,"logicalStepId"));ObjectNode view=Json.object("stepId",step==null?attempt.get("logicalStepId"):step.get("stepId"),"attemptNumber",attempt.get("attemptNumber"),"status",attempt.get("status"),"terminalAt",Json.get(attempt,"terminalAt"),"error",HandoffService.truncate(Json.text(attempt,"error",null),512));for(var pair:Map.of("requestedModelId",attempt.path("executorSnapshot"),"observedModelId",attempt.path("result")).entrySet()){String model=Json.text(pair.getValue(),pair.getKey(),null);if(model!=null&&!model.isEmpty()&&model.length()<=256)view.put(pair.getKey(),model);}ObjectNode efficiency=boundedEfficiencyProjection(attempt.get("efficiency"));if(efficiency!=null)view.set("efficiency",efficiency);attemptViews.add(view);}int pending=0,total=0;for(ObjectNode row:tx.query("SELECT status,count(*)::int n FROM approval_requests WHERE \"executionId\"=? GROUP BY status",id)){total+=Json.integer(row,"n",0);if(Json.text(row,"status").equals("PENDING"))pending=Json.integer(row,"n",0);}List<ObjectNode> artifactRows=tx.query("SELECT ar.id AS \"artifactId\",ar.\"descriptorOrdinal\",ar.\"descriptorHash\" FROM artifacts ar JOIN result_inbox i ON i.id=ar.\"resultInboxId\" JOIN step_attempts a ON a.id=i.\"stepAttemptId\" WHERE a.\"executionId\"=? ORDER BY ar.\"createdAt\" DESC LIMIT 64",id);ObjectNode graph=delegation.projection(id,100,tx.connection());return Json.object("schemaVersion",1,"serverTime",Instant.now().toString(),"execution",executionView,"coordination",coordination,"attempts",attemptViews,"attemptsTruncated",attempts.size()==200,"efficiency",aggregateEfficiency(attempts,attempts.size()==200),"approvals",Json.object("pending",pending,"decided",total),"artifacts",artifactRows,"artifactsTruncated",artifactRows.size()==64,"delegation",Json.object("supervisedTotal",graph.get("supervisedTotal"),"observedTotal",graph.get("observedTotal"),"truncated",Json.bool(graph,"supervisedTruncated",false)||Json.bool(graph,"observedTruncated",false)),"capsule",null,"bounds",BOUNDS.deepCopy());}
    public static ObjectNode boundedEfficiencyProjection(JsonNode raw){if(raw==null||raw.isNull())return null;ObjectNode e;try{e=ContextDomain.parseEfficiency(raw);}catch(RuntimeException error){return null;}JsonNode bundle=e.path("contextBundle"),context=e.path("context"),usage=e.path("usage"),timing=e.path("timing");ObjectNode view=Json.object("contextBundleHash",Json.get(bundle,"hash"),"contextBundleReused",Json.get(bundle,"reused"),"projectedBytes",Json.get(context,"projectedBytes"),"projectedCharacters",Json.get(context,"projectedCharacters"),"selectedContextItemCount",Json.get(context,"selectedContextItemCount"),"selectedArtifactCount",Json.get(context,"selectedArtifactCount"),"sessionMode",e.path("session").get("mode"),"usageReported",usage.get("reported"),"startedAt",timing.get("startedAt"),"completedAt",Json.get(timing,"completedAt"),"durationMs",Json.get(timing,"durationMs"));for(String key:List.of("inputTokens","outputTokens","cachedInputTokens","cacheWriteTokens"))if(usage.has(key))view.set(key,usage.get(key));if(e.path("harness").has("connectionId"))view.set("connectionId",e.path("harness").get("connectionId"));if(e.has("workspace"))view.set("workspaceId",e.path("workspace").get("workspaceId"));return view;}
    public static ObjectNode aggregateEfficiency(List<ObjectNode> attempts,boolean truncated){int bundles=0,reused=0,built=0,cacheEvidence=0,hits=0;long bytes=0,duration=0;boolean hasDuration=false;for(ObjectNode attempt:attempts){ObjectNode view=boundedEfficiencyProjection(attempt.get("efficiency"));if(view==null)continue;if(view.hasNonNull("contextBundleHash")){bundles++;if(Json.bool(view,"contextBundleReused",false))reused++;else built++;}bytes+=Json.longValue(view,"projectedBytes",0);if(Json.bool(view,"usageReported",false)&&view.has("cachedInputTokens")){cacheEvidence++;if(Json.longValue(view,"cachedInputTokens",0)>0)hits++;}if(view.hasNonNull("durationMs")){hasDuration=true;duration+=Json.longValue(view,"durationMs",0);}}return Json.object("attemptCount",attempts.size(),"bundleAttempts",bundles,"bundlesReused",reused,"bundlesBuilt",built,"projectedTotalBytes",bytes,"providerCacheEvidenceAttempts",cacheEvidence,"providerCacheHitAttempts",hits,"runtimeDurationMs",hasDuration?duration:null,"truncated",truncated);}
    private static ArrayNode boundedList(JsonNode list,int max){ArrayNode result=Json.array();if(list.isArray())for(JsonNode value:list){if(result.size()>=max)break;result.add(value);}return result;}
    private static int count(Db tx,String sql,String id){return Json.integer(tx.one(sql,id),"n",0);}
}
